public static double anteilUeber(int[] r, int grenze) {
    if (r.length == 0) {
        return 0.0;
    }
    int anzahl = 0;
    for (int i = 0; i < r.length; i++) {
        if (r[i] > grenze) {
            anzahl++;
        }
    }
    return 100.0 * anzahl / r.length;
}
